// Loop through all incoming items
for (const item of $input.all()) {
  const rawSchedule = item.json["المواعيد"];

  if (rawSchedule) {
    // 1. Split by comma
    // 2. Trim whitespace from each item
    // 3. Filter out any empty strings
    item.json.split_appointments = rawSchedule.split(',')
      .map(s => s.trim())
      .filter(s => s.length > 0);
  } else {
    item.json.split_appointments = [];
  }
}

return $input.all();

