// 2. Process every item coming from Google Sheets
for (const item of $input.all()) {
  const rawText = item.json["المواعيد"] || "";

  // Split the string by comma and clean whitespace
  const selections = rawText.split(',').map(s => s.trim());

  // Map the Arabic text to the IDs. If not found, keep original text
  item.json.appointment_ids = selections.map(choice => {
    return idMap[choice] || choice; 
  });
}

return $input.all();
